/**
 * Dashboard Sĩ số lớp
 * Load: Stored Procedure -> Dashboards/API/StudentClassSizeDashboardApi.ashx -> ApexCharts
 */
(function () {
    "use strict";

    var API_URL = "/Dashboards/API/StudentClassSizeDashboardApi.ashx";
    var CHART_PALETTE = [
        "#2563eb", "#dc2626", "#16a34a", "#ea580c", "#9333ea",
        "#0891b2", "#ca8a04", "#db2777", "#059669", "#4f46e5",
        "#0d9488", "#e11d48", "#7c3aed", "#0284c7", "#b45309"
    ];
    var PRIMARY = "#2563eb";
    var SUCCESS = "#16a34a";
    var DANGER = "#dc2626";
    var WARNING = "#ea580c";
    var INFO = "#0891b2";
    var MALE_COLOR = "#2563eb";
    var FEMALE_COLOR = "#e11d48";
    var MUTED = "#64748b";
    var CLASS_CHART_SCROLL_THRESHOLD = 15;

    var chartInstances = {};
    var lastPayload = null;
    var eventsBound = false;
    var filterConfig = window.scsDashFilterConfig || {};
    var lastFullscreenState = null;

    var baseChartOpts = {
        fontFamily: "inherit",
        foreColor: "#475569",
        toolbar: { show: false },
        width: "100%"
    };

    function formatNumber(val) {
        var num = parseInt(val, 10);
        if (isNaN(num)) {
            return "0";
        }
        return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    }

    function getEl(id) {
        return document.getElementById(id);
    }

    function showState(state) {
        var loading = getEl("scsDashStateLoading");
        var error = getEl("scsDashStateError");
        var empty = getEl("scsDashStateEmpty");
        var content = getEl("scsDashContent");

        if (loading) {
            loading.className = state === "loading" ? "scs-dash-state" : "scs-dash-state d-none";
        }
        if (error) {
            error.className = state === "error" ? "scs-dash-state" : "scs-dash-state d-none";
        }
        if (empty) {
            empty.className = state === "empty" ? "scs-dash-state" : "scs-dash-state d-none";
        }
        if (content) {
            content.style.display = (state === "ready" || state === "empty") ? "" : "none";
        }
    }

    function setErrorMessage(message) {
        var el = getEl("scsDashErrorMessage");
        if (el) {
            el.textContent = message || "Có lỗi xảy ra.";
        }
    }

    function postJson(payload, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open("POST", API_URL, true);
        xhr.setRequestHeader("Content-Type", "application/json; charset=utf-8");
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) {
                return;
            }
            if (xhr.status !== 200) {
                callback(false, "Không kết nối được API dashboard (HTTP " + xhr.status + ").", null);
                return;
            }
            var response = null;
            try {
                response = JSON.parse(xhr.responseText);
            } catch (e) {
                callback(false, "Phản hồi không hợp lệ từ máy chủ.", null);
                return;
            }
            if (!response || !response.success) {
                callback(false, response && response.message ? response.message : "Không tải được dữ liệu.", null);
                return;
            }
            callback(true, "", response.data);
        };
        xhr.onerror = function () {
            callback(false, "Lỗi mạng khi gọi API dashboard.", null);
        };
        xhr.send(JSON.stringify(payload));
    }

    function getSelectValue(clientId) {
        if (!clientId) {
            return "";
        }
        var el = document.getElementById(clientId);
        return el ? el.value : "";
    }

    function readFilterConfig() {
        filterConfig = window.scsDashFilterConfig || filterConfig || {};
        return filterConfig;
    }

    function isFilterValueActive(val) {
        return val !== null && val !== undefined && val !== "" && val !== "0" && val !== "-1";
    }

    function getViewLevel(filters) {
        var hasScience = isFilterValueActive(filters.scienceId);
        var hasCourse = isFilterValueActive(filters.courseId);
        var hasClass = isFilterValueActive(filters.classId);

        if (hasClass || (hasScience && hasCourse)) {
            return "byClass";
        }
        if (hasScience && !hasCourse) {
            return "byCourse";
        }
        if (!hasScience && hasCourse) {
            return "byScience";
        }
        return "overview";
    }

    function setChartMode(viewLevel) {
        var rowClass = getEl("scsDashRowClassCharts");
        var rowOverview = getEl("scsDashRowOverviewCharts");
        var isClassView = viewLevel === "byClass";

        if (rowClass) {
            rowClass.className = isClassView ? "row sch-dash-row" : "row sch-dash-row d-none";
        }
        if (rowOverview) {
            rowOverview.className = isClassView ? "row sch-dash-row d-none" : "row sch-dash-row";
        }
    }

    function setPrimaryChartTitles(viewLevel) {
        var titleOverview = getEl("scsDashPrimaryTitleOverview");
        var titleClass = getEl("scsDashPrimaryTitleClass");
        var titleGenderOverview = getEl("scsDashGenderTitleOverview");
        var titleGenderClass = getEl("scsDashGenderTitleClass");

        if (titleOverview) {
            if (viewLevel === "byCourse") {
                titleOverview.textContent = "Sĩ số theo khóa (trong khoa đã chọn)";
            } else if (viewLevel === "byScience") {
                titleOverview.textContent = "Sĩ số theo khoa / ngành (trong khóa đã chọn)";
            } else {
                titleOverview.textContent = "Sĩ số theo khóa";
            }
        }
        if (titleClass) {
            titleClass.textContent = "Sĩ số theo lớp";
        }
        if (titleGenderOverview) {
            if (viewLevel === "overview") {
                titleGenderOverview.textContent = "Tỷ lệ nam / nữ toàn trường";
            } else {
                titleGenderOverview.textContent = "Tỷ lệ nam / nữ (theo bộ lọc)";
            }
        }
        if (titleGenderClass) {
            titleGenderClass.textContent = "Tỷ lệ nam / nữ theo lớp";
        }
    }

    function fillFilterDropdown(clientId, rows, valueField, textField) {
        var el = document.getElementById(clientId);
        var i;
        var row;

        if (!el) {
            return;
        }

        while (el.options.length > 0) {
            el.remove(0);
        }

        var defaultOpt = document.createElement("option");
        defaultOpt.value = "";
        defaultOpt.text = "--Chọn--";
        el.appendChild(defaultOpt);

        if (!rows || rows.length === 0) {
            return;
        }

        for (i = 0; i < rows.length; i++) {
            row = rows[i];
            var opt = document.createElement("option");
            opt.value = row[valueField] !== null && row[valueField] !== undefined ? String(row[valueField]) : "";
            opt.text = row[textField] !== null && row[textField] !== undefined ? String(row[textField]) : "";
            el.appendChild(opt);
        }
    }

    function resetFilterDropdown(clientId) {
        fillFilterDropdown(clientId, [], "", "");
    }

    function loadFilterList(listType, scienceId, courseId, callback) {
        postJson({
            action: "filters",
            listType: listType,
            scienceId: scienceId || "",
            courseId: courseId || ""
        }, function (success, message, data) {
            if (!success) {
                callback(false, message, []);
                return;
            }
            callback(true, "", data && data.items ? data.items : []);
        });
    }

    function onScienceFilterChange() {
        readFilterConfig();
        var scienceId = getSelectValue(filterConfig.scienceId);

        resetFilterDropdown(filterConfig.courseId);
        resetFilterDropdown(filterConfig.classId);

        if (!isFilterValueActive(scienceId)) {
            return;
        }

        loadFilterList(2, scienceId, "", function (success, message, rows) {
            if (success) {
                fillFilterDropdown(filterConfig.courseId, rows, "CourseID", "CourseName");
            }
        });
    }

    function onCourseFilterChange() {
        readFilterConfig();
        var scienceId = getSelectValue(filterConfig.scienceId);
        var courseId = getSelectValue(filterConfig.courseId);

        resetFilterDropdown(filterConfig.classId);

        if (!isFilterValueActive(courseId)) {
            return;
        }

        loadFilterList(3, scienceId, courseId, function (success, message, rows) {
            if (success) {
                fillFilterDropdown(filterConfig.classId, rows, "ClassID", "ClassName");
            }
        });
    }

    function getFiltersFromDom() {
        readFilterConfig();
        return {
            scienceId: getSelectValue(filterConfig.scienceId),
            courseId: getSelectValue(filterConfig.courseId),
            classId: getSelectValue(filterConfig.classId)
        };
    }

    function loadDashboardData(callback) {
        var filters = getFiltersFromDom();

        lastPayload = filters;
        postJson({
            action: "data",
            scienceId: filters.scienceId,
            courseId: filters.courseId,
            classId: filters.classId
        }, callback);
    }

    function destroyChart(id) {
        if (chartInstances[id]) {
            chartInstances[id].destroy();
            chartInstances[id] = null;
        }
    }

    function setScrollWrapHeight(wrapEl, itemCount, rowHeight) {
        if (!wrapEl) {
            return;
        }
        var maxHeight = 420;
        var minHeight = 280;
        var calculated = itemCount * rowHeight + 48;
        var height = calculated > maxHeight ? maxHeight : calculated;
        if (height < minHeight) {
            height = minHeight;
        }
        wrapEl.style.maxHeight = height + "px";
        wrapEl.style.overflowY = itemCount * rowHeight + 48 > maxHeight ? "auto" : "visible";
    }

    function resetScrollWrap(wrapEl) {
        if (!wrapEl) {
            return;
        }
        wrapEl.style.maxHeight = "";
        wrapEl.style.overflowY = "";
    }

    function renderChart(id, options, emptyId) {
        var el = document.querySelector(id);
        var emptyEl = emptyId ? getEl(emptyId) : null;

        if (!el || typeof ApexCharts === "undefined") {
            return;
        }

        destroyChart(id);

        if (!options || options.isEmpty) {
            el.innerHTML = "";
            if (emptyEl) {
                emptyEl.className = "scs-dash-chart-empty";
            }
            return;
        }

        if (emptyEl) {
            emptyEl.className = "scs-dash-chart-empty d-none";
        }

        chartInstances[id] = new ApexCharts(el, options);
        chartInstances[id].render();
    }

    function toggleChartEmpty(chartId, emptyId, isEmpty) {
        var chartEl = document.querySelector(chartId);
        if (chartEl) {
            chartEl.style.display = isEmpty ? "none" : "";
        }
        if (emptyId) {
            var emptyEl = getEl(emptyId);
            if (emptyEl) {
                emptyEl.className = isEmpty ? "scs-dash-chart-empty" : "scs-dash-chart-empty d-none";
            }
        }
    }

    function buildHorizontalBarOptions(labels, series, seriesName, chartHeight, useDistributed) {
        return {
            series: [{ name: seriesName || "Sĩ số", data: series }],
            chart: Object.assign({ height: chartHeight, type: "bar" }, baseChartOpts),
            plotOptions: {
                bar: {
                    horizontal: true,
                    borderRadius: 6,
                    barHeight: labels.length > 8 ? "72%" : "65%",
                    distributed: useDistributed === true
                }
            },
            colors: useDistributed === true ? CHART_PALETTE : [PRIMARY],
            dataLabels: {
                enabled: true,
                style: {
                    colors: ["#fff"],
                    fontSize: "11px",
                    fontWeight: 600
                }
            },
            xaxis: {
                categories: labels,
                title: { text: "Sinh viên" },
                labels: {
                    formatter: function (val) {
                        return formatNumber(val);
                    }
                }
            },
            yaxis: {
                labels: {
                    maxWidth: 180,
                    style: { fontSize: "11px" }
                }
            },
            grid: { strokeDashArray: 4, borderColor: "#e2e8f0" },
            legend: { show: false },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return formatNumber(val) + " sinh viên";
                    }
                }
            }
        };
    }

    function buildVerticalBarOptions(labels, series, seriesName, chartHeight) {
        return {
            series: [{ name: seriesName || "Sĩ số", data: series }],
            chart: Object.assign({ height: chartHeight, type: "bar" }, baseChartOpts),
            plotOptions: {
                bar: {
                    borderRadius: 6,
                    columnWidth: labels.length > 10 ? "78%" : "55%",
                    distributed: true
                }
            },
            colors: CHART_PALETTE,
            dataLabels: {
                enabled: labels.length <= 12,
                style: {
                    colors: ["#fff"],
                    fontSize: "10px",
                    fontWeight: 600
                }
            },
            xaxis: {
                categories: labels,
                labels: {
                    rotate: labels.length > 8 ? -45 : 0,
                    trim: true,
                    maxHeight: 90,
                    style: { fontSize: "10px" }
                }
            },
            yaxis: {
                title: { text: "Sinh viên" },
                labels: {
                    formatter: function (val) {
                        return formatNumber(val);
                    }
                }
            },
            grid: { strokeDashArray: 4, borderColor: "#e2e8f0" },
            legend: { show: false },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return formatNumber(val) + " sinh viên";
                    }
                }
            }
        };
    }

    function buildStackedHorizontalOptions(labels, maleSeries, femaleSeries, chartHeight) {
        return {
            series: [
                { name: "Nam", data: maleSeries },
                { name: "Nữ", data: femaleSeries }
            ],
            chart: Object.assign({ height: chartHeight, type: "bar", stacked: true }, baseChartOpts),
            plotOptions: {
                bar: {
                    horizontal: true,
                    borderRadius: 4,
                    barHeight: labels.length > 8 ? "72%" : "65%"
                }
            },
            colors: [MALE_COLOR, FEMALE_COLOR],
            dataLabels: {
                enabled: labels.length <= 12,
                style: {
                    colors: ["#fff"],
                    fontSize: "10px",
                    fontWeight: 600
                }
            },
            xaxis: {
                categories: labels,
                labels: {
                    formatter: function (val) {
                        return formatNumber(val);
                    }
                }
            },
            yaxis: {
                labels: {
                    maxWidth: 180,
                    style: { fontSize: "11px" }
                }
            },
            legend: { position: "top", fontWeight: 600 },
            grid: { strokeDashArray: 4, borderColor: "#e2e8f0" },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return formatNumber(val) + " sinh viên";
                    }
                }
            }
        };
    }

    function buildStackedVerticalOptions(labels, maleSeries, femaleSeries, chartHeight) {
        return {
            series: [
                { name: "Nam", data: maleSeries },
                { name: "Nữ", data: femaleSeries }
            ],
            chart: Object.assign({ height: chartHeight, type: "bar", stacked: true }, baseChartOpts),
            plotOptions: {
                bar: {
                    horizontal: false,
                    borderRadius: 4,
                    columnWidth: labels.length > 10 ? "78%" : "55%"
                }
            },
            colors: [MALE_COLOR, FEMALE_COLOR],
            dataLabels: {
                enabled: labels.length <= 10,
                style: {
                    colors: ["#fff"],
                    fontSize: "10px",
                    fontWeight: 600
                }
            },
            xaxis: {
                categories: labels,
                labels: {
                    rotate: labels.length > 6 ? -45 : 0,
                    trim: true,
                    style: { fontSize: "10px" }
                }
            },
            legend: { position: "top", fontWeight: 600 },
            grid: { strokeDashArray: 4, borderColor: "#e2e8f0" }
        };
    }

    function buildDonutOptions(labels, series, centerLabel) {
        return {
            series: series,
            chart: Object.assign({ height: 320, type: "donut" }, baseChartOpts),
            labels: labels,
            colors: CHART_PALETTE,
            plotOptions: {
                pie: {
                    donut: {
                        size: "62%",
                        labels: {
                            show: true,
                            total: {
                                show: true,
                                label: centerLabel || "Tổng SV",
                                fontWeight: 700,
                                color: "#1e293b"
                            },
                            value: {
                                fontWeight: 700,
                                color: "#1e293b"
                            }
                        }
                    }
                }
            },
            dataLabels: {
                enabled: true,
                style: {
                    fontSize: "11px",
                    fontWeight: 600
                },
                dropShadow: { enabled: false }
            },
            legend: {
                position: "bottom",
                fontWeight: 600
            },
            stroke: { width: 2, colors: ["#fff"] }
        };
    }

    function updateKpiCards(summaryRows) {
        var summary = (summaryRows && summaryRows.length > 0) ? summaryRows[0] : {};
        var map = {
            "scs-kpi-classes": summary.TotalClass,
            "scs-kpi-students": summary.TotalStudent,
            "scs-kpi-studying": summary.StudyingStudent,
            "scs-kpi-warning": summary.WarningStudent
        };
        var key;

        for (key in map) {
            if (!map.hasOwnProperty(key)) {
                continue;
            }
            var card = getEl(key);
            if (!card) {
                continue;
            }
            var valueEl = card.querySelector(".sch-dash-kpi-value");
            if (valueEl) {
                valueEl.textContent = formatNumber(map[key]);
            }
        }
    }

    function registerFullscreenState(title, targetId, optionsBuilder) {
        lastFullscreenState = {
            title: title,
            targetId: targetId,
            optionsBuilder: optionsBuilder
        };
    }

    function renderPrimaryBarChart(targetId, emptyId, scrollWrapId, labels, series, seriesName, fullscreenTitle) {
        var useHorizontal = labels.length > CLASS_CHART_SCROLL_THRESHOLD;
        var chartHeight = useHorizontal ? Math.max(280, labels.length * 32 + 60) : 320;
        var scrollWrap = scrollWrapId ? getEl(scrollWrapId) : null;
        var options;

        if (labels.length === 0) {
            destroyChart(targetId);
            toggleChartEmpty(targetId, emptyId, true);
            resetScrollWrap(scrollWrap);
            return;
        }

        toggleChartEmpty(targetId, emptyId, false);

        if (useHorizontal) {
            if (scrollWrap) {
                scrollWrap.className = "scs-dash-chart-scroll-wrap";
                setScrollWrapHeight(scrollWrap, labels.length, 32);
            }
            options = buildHorizontalBarOptions(labels, series, seriesName, chartHeight, true);
        } else {
            resetScrollWrap(scrollWrap);
            if (scrollWrap) {
                scrollWrap.className = "";
            }
            options = buildVerticalBarOptions(labels, series, seriesName, chartHeight);
        }

        renderChart(targetId, options, emptyId);
        registerFullscreenState(fullscreenTitle, targetId, function () {
            var fsHeight = Math.max(480, labels.length * 34 + 80);
            if (useHorizontal) {
                return buildHorizontalBarOptions(labels, series, seriesName, fsHeight, true);
            }
            return buildVerticalBarOptions(labels, series, seriesName, fsHeight);
        });
    }

    function renderByClassChart(targetId, emptyId, scrollWrapId, rows, fullscreenTitle) {
        var labels = [];
        var series = [];
        var i;

        for (i = 0; i < rows.length; i++) {
            labels.push(rows[i].ClassName);
            series.push(rows[i].StudentCount || 0);
        }

        renderPrimaryBarChart(targetId, emptyId, scrollWrapId, labels, series, "Sĩ số", fullscreenTitle);
    }

    function renderGenderChart(rows, scrollWrapId, fullscreenTitle) {
        var labels = [];
        var maleSeries = [];
        var femaleSeries = [];
        var useHorizontal = rows.length > CLASS_CHART_SCROLL_THRESHOLD;
        var chartHeight = useHorizontal ? Math.max(280, rows.length * 32 + 60) : 320;
        var scrollWrap = scrollWrapId ? getEl(scrollWrapId) : null;
        var i;
        var options;

        for (i = 0; i < rows.length; i++) {
            labels.push(rows[i].ClassName);
            maleSeries.push(rows[i].MaleQuantity || 0);
            femaleSeries.push(rows[i].FemaleQuantity || 0);
        }

        if (labels.length === 0) {
            destroyChart("#scsDashChartGender");
            toggleChartEmpty("#scsDashChartGender", "scsDashChartGenderEmpty", true);
            resetScrollWrap(scrollWrap);
            return;
        }

        toggleChartEmpty("#scsDashChartGender", "scsDashChartGenderEmpty", false);

        if (useHorizontal) {
            if (scrollWrap) {
                scrollWrap.className = "scs-dash-chart-scroll-wrap";
                setScrollWrapHeight(scrollWrap, labels.length, 32);
            }
            options = buildStackedHorizontalOptions(labels, maleSeries, femaleSeries, chartHeight);
        } else {
            resetScrollWrap(scrollWrap);
            if (scrollWrap) {
                scrollWrap.className = "";
            }
            options = buildStackedVerticalOptions(labels, maleSeries, femaleSeries, chartHeight);
        }

        renderChart("#scsDashChartGender", options, "scsDashChartGenderEmpty");
    }

    function renderByScienceChart(rows) {
        var labels = [];
        var series = [];
        var i;

        for (i = 0; i < rows.length; i++) {
            labels.push(rows[i].ScienceName);
            series.push(rows[i].StudentCount || 0);
        }

        if (labels.length === 0) {
            destroyChart("#scsDashChartByScience");
            toggleChartEmpty("#scsDashChartByScience", "scsDashChartByScienceEmpty", true);
            return;
        }

        toggleChartEmpty("#scsDashChartByScience", "scsDashChartByScienceEmpty", false);
        renderChart("#scsDashChartByScience", buildHorizontalBarOptions(labels, series, "Sĩ số", 320, true), "scsDashChartByScienceEmpty");
    }

    function normalizeOverviewRows(byCourseRows, byScienceRows) {
        var rows = byCourseRows || [];
        var normalized = [];
        var i;

        if (rows.length > 0) {
            for (i = 0; i < rows.length; i++) {
                normalized.push({
                    label: rows[i].CourseName || rows[i].courseName || ("Khóa " + (i + 1)),
                    value: rows[i].StudentCount || rows[i].studentCount || 0
                });
            }
            return normalized;
        }

        rows = byScienceRows || [];
        for (i = 0; i < rows.length; i++) {
            normalized.push({
                label: rows[i].ScienceName || rows[i].scienceName || ("Khoa " + (i + 1)),
                value: rows[i].StudentCount || rows[i].studentCount || 0
            });
        }
        return normalized;
    }

    function renderOverviewPrimaryChart(rows, fallbackRows, chartTitle, fullscreenTitle) {
        var normalized = normalizeOverviewRows(rows, fallbackRows);
        var labels = [];
        var series = [];
        var i;

        for (i = 0; i < normalized.length; i++) {
            labels.push(normalized[i].label);
            series.push(normalized[i].value);
        }

        renderPrimaryBarChart("#scsDashChartByCourse", "scsDashChartByCourseEmpty", null, labels, series, chartTitle || "Sĩ số", fullscreenTitle);
    }

    function renderGenderOverviewChart(rows) {
        var maleTotal = 0;
        var femaleTotal = 0;
        var i;

        for (i = 0; i < rows.length; i++) {
            maleTotal += rows[i].MaleQuantity || 0;
            femaleTotal += rows[i].FemaleQuantity || 0;
        }

        if (maleTotal === 0 && femaleTotal === 0) {
            destroyChart("#scsDashChartGenderOverview");
            toggleChartEmpty("#scsDashChartGenderOverview", "scsDashChartGenderOverviewEmpty", true);
            return;
        }

        toggleChartEmpty("#scsDashChartGenderOverview", "scsDashChartGenderOverviewEmpty", false);
        renderChart("#scsDashChartGenderOverview", buildDonutOptions(["Nam", "Nữ"], [maleTotal, femaleTotal], "Tổng SV"), "scsDashChartGenderOverviewEmpty");
    }

    function getWarningBadgeClass(warningType) {
        var map = {
            "Thấp": "scs-dash-badge-low",
            "Cao": "scs-dash-badge-high",
            "Giảm mạnh": "scs-dash-badge-drop",
            "Nghỉ nhiều": "scs-dash-badge-absent",
            "Cảnh báo": "scs-dash-badge-warn"
        };
        return map[warningType] || "scs-dash-badge-warn";
    }

    function renderAbnormalList(rows) {
        var container = getEl("scsDashAbnormalList");
        var emptyEl = getEl("scsDashAbnormalEmpty");
        var summaryEl = getEl("scsDashAbnormalSummary");
        var i;
        var row;
        var html = [];
        var lowCount = 0;
        var highCount = 0;
        var otherCount = 0;

        if (!container) {
            return;
        }

        if (!rows || rows.length === 0) {
            container.innerHTML = "";
            container.className = "scs-dash-abnormal-list d-none";
            if (emptyEl) {
                emptyEl.className = "scs-dash-chart-empty";
            }
            if (summaryEl) {
                summaryEl.className = "scs-dash-abnormal-summary d-none";
            }
            return;
        }

        for (i = 0; i < rows.length; i++) {
            row = rows[i];
            if (row.WarningType === "Thấp" || row.WarningType === "Giảm mạnh") {
                lowCount += 1;
            } else if (row.WarningType === "Cao") {
                highCount += 1;
            } else {
                otherCount += 1;
            }

            html.push("<tr>");
            html.push("<td><strong>" + (row.ClassName || "") + "</strong></td>");
            html.push("<td>" + (row.ScienceName || "") + "</td>");
            html.push("<td class=\"text-center\"><span class=\"scs-dash-badge " + getWarningBadgeClass(row.WarningType) + "\">" + (row.WarningType || "Cảnh báo") + "</span></td>");
            html.push("<td class=\"text-end\">" + formatNumber(row.ClassSize) + "</td>");
            html.push("<td class=\"text-end\"><strong>" + formatNumber(row.StudyQuantity) + "</strong></td>");
            html.push("<td class=\"text-end\">" + formatNumber(row.NowStudentCount) + "</td>");
            html.push("</tr>");
        }

        container.innerHTML = "<table class=\"table table-sm scs-dash-abnormal-table mb-0\"><thead><tr>"
            + "<th>Lớp</th><th>Khoa</th><th class=\"text-center\">Loại</th>"
            + "<th class=\"text-end\">Chỉ tiêu</th><th class=\"text-end\">Đang học</th><th class=\"text-end\">Tổng SV</th>"
            + "</tr></thead><tbody>" + html.join("") + "</tbody></table>";
        container.className = "scs-dash-abnormal-list";

        if (emptyEl) {
            emptyEl.className = "scs-dash-chart-empty d-none";
        }
        if (summaryEl) {
            summaryEl.innerHTML = "<span class=\"scs-dash-abnormal-chip scs-dash-badge-low\">Thấp: " + formatNumber(lowCount) + "</span>"
                + "<span class=\"scs-dash-abnormal-chip scs-dash-badge-high\">Cao: " + formatNumber(highCount) + "</span>"
                + "<span class=\"scs-dash-abnormal-chip scs-dash-badge-warn\">Khác: " + formatNumber(otherCount) + "</span>";
            summaryEl.className = "scs-dash-abnormal-summary";
        }
    }

    function renderDashboard(data) {
        var filters = getFiltersFromDom();
        var viewLevel = getViewLevel(filters);
        var summary = (data.summary && data.summary.length > 0) ? data.summary[0] : {};
        var isEmpty = (parseInt(summary.TotalClass, 10) || 0) === 0;

        try {
            setChartMode(viewLevel);
            setPrimaryChartTitles(viewLevel);
            updateKpiCards(data.summary || []);

            if (viewLevel === "byClass") {
                renderByClassChart("#scsDashChartByClass", "scsDashChartByClassEmpty", "scsDashChartByClassScroll", data.byClass || [], "Sĩ số theo lớp");
                renderGenderChart(data.genderByClass || [], "scsDashChartGenderScroll", "Tỷ lệ nam / nữ theo lớp");
                destroyChart("#scsDashChartByCourse");
                destroyChart("#scsDashChartGenderOverview");
            } else if (viewLevel === "byScience") {
                renderOverviewPrimaryChart([], data.byScience || [], "Sĩ số", "Sĩ số theo khoa / ngành");
                renderGenderOverviewChart(data.genderByClass || []);
                destroyChart("#scsDashChartByClass");
                destroyChart("#scsDashChartGender");
            } else if (viewLevel === "byCourse") {
                renderOverviewPrimaryChart(data.byCourse || [], [], "Sĩ số", "Sĩ số theo khóa");
                renderGenderOverviewChart(data.genderByClass || []);
                destroyChart("#scsDashChartByClass");
                destroyChart("#scsDashChartGender");
            } else {
                renderOverviewPrimaryChart(data.byCourse || [], data.byScience || [], "Sĩ số", "Sĩ số theo khóa");
                renderGenderOverviewChart(data.genderByClass || []);
                destroyChart("#scsDashChartByClass");
                destroyChart("#scsDashChartGender");
            }

            renderByScienceChart(data.byScience || []);
            renderAbnormalList(data.abnormal || []);
        } catch (ex) {
            setErrorMessage("Lỗi hiển thị biểu đồ: " + (ex.message || "không xác định"));
            showState("error");
            return;
        }

        var updateTime = getEl("scsDashUpdateTime");
        if (updateTime) {
            updateTime.textContent = data.updatedAt || "--/--/---- --:--";
        }

        showState(isEmpty ? "empty" : "ready");
    }

    function setButtonsLoading(isLoading) {
        var btnLoad = getEl("scsDashBtnLoad");
        var btnRefresh = getEl("scsDashBtnRefresh");
        if (btnLoad) {
            btnLoad.disabled = isLoading;
        }
        if (btnRefresh) {
            btnRefresh.className = isLoading ? "btn btn-outline-secondary scs-dash-btn-outline is-loading" : "btn btn-outline-secondary scs-dash-btn-outline";
            btnRefresh.disabled = isLoading;
        }
    }

    function fetchDashboard() {
        showState("loading");
        setButtonsLoading(true);
        setErrorMessage("");

        loadDashboardData(function (success, message, data) {
            setButtonsLoading(false);
            if (!success) {
                setErrorMessage(message);
                showState("error");
                return;
            }
            try {
                renderDashboard(data);
            } catch (ex) {
                setErrorMessage("Lỗi xử lý dữ liệu dashboard.");
                showState("error");
            }
        });
    }

    function openFullscreen() {
        var overlay = getEl("scsDashFullscreenOverlay");
        var titleEl = getEl("scsDashFullscreenTitle");
        var options;

        if (!overlay || !lastFullscreenState || !lastFullscreenState.optionsBuilder) {
            return;
        }

        if (titleEl) {
            titleEl.textContent = lastFullscreenState.title || "Biểu đồ chi tiết";
        }

        options = lastFullscreenState.optionsBuilder();
        renderChart("#scsDashChartPrimaryFullscreen", options, null);

        overlay.className = "scs-dash-fullscreen";
        document.body.style.overflow = "hidden";

        if (chartInstances["#scsDashChartPrimaryFullscreen"]) {
            chartInstances["#scsDashChartPrimaryFullscreen"].windowResizeHandler();
        }
    }

    function closeFullscreen() {
        var overlay = getEl("scsDashFullscreenOverlay");
        if (!overlay) {
            return;
        }
        overlay.className = "scs-dash-fullscreen d-none";
        document.body.style.overflow = "";
        destroyChart("#scsDashChartPrimaryFullscreen");
    }

    function bindEvents() {
        if (eventsBound) {
            return;
        }
        eventsBound = true;

        var btnLoad = getEl("scsDashBtnLoad");
        var btnRefresh = getEl("scsDashBtnRefresh");
        var btnFullscreenOverview = getEl("scsDashBtnFullscreenOverview");
        var btnFullscreenClass = getEl("scsDashBtnFullscreenClass");
        var btnCloseFullscreen = getEl("scsDashBtnCloseFullscreen");

        if (btnLoad) {
            btnLoad.addEventListener("click", fetchDashboard);
        }
        if (btnRefresh) {
            btnRefresh.addEventListener("click", fetchDashboard);
        }
        if (btnFullscreenOverview) {
            btnFullscreenOverview.addEventListener("click", openFullscreen);
        }
        if (btnFullscreenClass) {
            btnFullscreenClass.addEventListener("click", openFullscreen);
        }
        if (btnCloseFullscreen) {
            btnCloseFullscreen.addEventListener("click", closeFullscreen);
        }

        readFilterConfig();
        var scienceEl = document.getElementById(filterConfig.scienceId);
        var courseEl = document.getElementById(filterConfig.courseId);
        if (scienceEl) {
            scienceEl.addEventListener("change", onScienceFilterChange);
        }
        if (courseEl) {
            courseEl.addEventListener("change", onCourseFilterChange);
        }

        window.addEventListener("resize", function () {
            var key;
            for (key in chartInstances) {
                if (chartInstances.hasOwnProperty(key) && chartInstances[key]) {
                    chartInstances[key].windowResizeHandler();
                }
            }
        });
    }

    function initStudentClassSizeDashboard() {
        if (!getEl("scsDashBtnLoad")) {
            return;
        }

        readFilterConfig();
        bindEvents();
        showState("loading");
        fetchDashboard();
    }

    function bootStudentClassSizeDashboard() {
        if (document.readyState === "loading") {
            document.addEventListener("DOMContentLoaded", initStudentClassSizeDashboard);
        } else {
            initStudentClassSizeDashboard();
        }
    }

    bootStudentClassSizeDashboard();
})();

