function getWarningTypeColor(warningType) {
    var map = {
        "Thấp": "#dc2626",
        "Cao": "#ea580c",
        "Giảm mạnh": "#991b1b",
        "Nghỉ nhiều": "#ca8a04",
        "Cảnh báo": "#64748b"
    };
    return map[warningType] || "#64748b";
}

function aggregateAbnormalStats(rows) {
    var typeMap = {};
    var scienceMap = {};
    var totalStudy = 0;
    var totalClassSize = 0;
    var totalGap = 0;
    var i;
    var row;
    var warningType;
    var scienceName;
    var gap;

    for (i = 0; i < rows.length; i++) {
        row = rows[i];
        warningType = row.WarningType || "Cảnh báo";
        scienceName = row.ScienceName || "Khác";
        typeMap[warningType] = (typeMap[warningType] || 0) + 1;
        scienceMap[scienceName] = (scienceMap[scienceName] || 0) + 1;
        totalStudy += parseInt(row.StudyQuantity, 10) || 0;
        totalClassSize += parseInt(row.ClassSize, 10) || 0;
        gap = (parseInt(row.StudyQuantity, 10) || 0) - (parseInt(row.ClassSize, 10) || 0);
        totalGap += gap >= 0 ? gap : gap * -1;
    }

    return {
        typeMap: typeMap,
        scienceMap: scienceMap,
        totalClasses: rows.length,
        totalStudy: totalStudy,
        totalClassSize: totalClassSize,
        avgGap: rows.length > 0 ? Math.round(totalGap / rows.length) : 0
    };
}

function mapToSortedSeries(mapObj, limit) {
    var labels = [];
    var series = [];
    var pairs = [];
    var key;

    for (key in mapObj) {
        if (mapObj.hasOwnProperty(key)) {
            pairs.push({ label: key, value: mapObj[key] });
        }
    }
    pairs.sort(function (a, b) {
        return b.value - a.value;
    });
    if (limit && pairs.length > limit) {
        pairs = pairs.slice(0, limit);
    }
    for (var i = 0; i < pairs.length; i++) {
        labels.push(pairs[i].label);
        series.push(pairs[i].value);
    }
    return { labels: labels, series: series };
}

