function normalizeStatusRows(rows) {
    var map = {};
    var labels = [];
    var series = [];
    var colors = [];
    var total = 0;
    var studying = 0;
    var inactive = 0;
    var i;
    var row;
    var code;
    var count;

    for (i = 0; i < STATUS_DEFS.length; i++) {
        map[STATUS_DEFS[i].code] = 0;
    }
    for (i = 0; i < rows.length; i++) {
        row = rows[i];
        code = parseInt(row.Status, 10);
        if (isNaN(code)) {
            code = -1;
        }
        count = parseInt(row.StudentCount, 10) || 0;
        if (map[code] === undefined) {
            map[code] = 0;
        }
        map[code] += count;
    }
    for (i = 0; i < STATUS_DEFS.length; i++) {
        code = STATUS_DEFS[i].code;
        count = map[code] || 0;
        if (count <= 0) {
            continue;
        }
        labels.push(STATUS_DEFS[i].name);
        series.push(count);
        colors.push(STATUS_DEFS[i].color);
        total += count;
        if (code === 1) {
            studying = count;
        }
        if (code !== 1 && code !== 2) {
            inactive += count;
        }
    }
    return {
        labels: labels,
        series: series,
        colors: colors,
        total: total,
        studying: studying,
        inactive: inactive
    };
