function buildStatusByScienceChart(rows) {
    var scienceTotals = {};
    var scienceStatus = {};
    var scienceNames = [];
    var statusCodes = [];
    var series = [];
    var i;
    var row;
    var scienceName;
    var statusCode;
    var count;
    var j;
    var topSciences;

    for (i = 0; i < rows.length; i++) {
        row = rows[i];
        scienceName = row.ScienceName || "Khác";
        statusCode = parseInt(row.Status, 10);
        count = parseInt(row.StudentCount, 10) || 0;
        if (!scienceTotals[scienceName]) {
            scienceTotals[scienceName] = 0;
            scienceStatus[scienceName] = {};
        }
        scienceTotals[scienceName] += count;
        if (!scienceStatus[scienceName][statusCode]) {
            scienceStatus[scienceName][statusCode] = 0;
        }
        scienceStatus[scienceName][statusCode] += count;
    }

    topSciences = [];
    for (scienceName in scienceTotals) {
        if (scienceTotals.hasOwnProperty(scienceName)) {
            topSciences.push({ name: scienceName, total: scienceTotals[scienceName] });
        }
    }
    topSciences.sort(function (a, b) {
        return b.total - a.total;
    });
    if (topSciences.length > 8) {
        topSciences = topSciences.slice(0, 8);
    }

    for (i = 0; i < STATUS_DEFS.length; i++) {
