        for (j = 0; j < topSciences.length; j++) {
            scienceName = topSciences[j].name;
            if (!scienceNames[j]) {
                scienceNames[j] = scienceName;
            }
            series.push({
                name: getStatusName(statusCode),
                data: []
            });
        }
    }

    series = [];
    for (i = 0; i < statusCodes.length; i++) {
        statusCode = statusCodes[i];
        var dataSeries = [];
        var statusTotal = 0;
        for (j = 0; j < topSciences.length; j++) {
            scienceName = topSciences[j].name;
            count = (scienceStatus[scienceName] && scienceStatus[scienceName][statusCode]) ? scienceStatus[scienceName][statusCode] : 0;
            dataSeries.push(count);
            statusTotal += count;
        }
        if (statusTotal > 0) {
            series.push({
                name: getStatusName(statusCode),
                data: dataSeries
            });
        }
    }

    scienceNames = [];
    for (j = 0; j < topSciences.length; j++) {
        scienceNames.push(topSciences[j].name);
    }

    return {
