function prepareClassLineData(rows) {
    var pairs = [];
    var i;
    for (i = 0; i < rows.length; i++) {
        pairs.push({
            label: rows[i].ClassName || "",
            studentCount: parseInt(rows[i].StudentCount, 10) || 0,
            studyQuantity: parseInt(rows[i].StudyQuantity, 10) || 0,
            classSize: parseInt(rows[i].ClassSize, 10) || 0
        });
    }
    pairs.sort(function (a, b) {
        return b.studentCount - a.studentCount;
    });
    return pairs;
}

function pairsToLineSeries(pairs) {
    var labels = [];
    var students = [];
    var studying = [];
    var targets = [];
    var i;
    for (i = 0; i < pairs.length; i++) {
        labels.push(pairs[i].label);
        students.push(pairs[i].studentCount);
        studying.push(pairs[i].studyQuantity);
        targets.push(pairs[i].classSize);
    }
    return {
        labels: labels,
        students: students,
        studying: studying,
        targets: targets
    };
}

function buildModernLineChartOptions(labels, students, studying, targets, chartHeight, isFullscreen) {
    return {
        series: [
            { name: "T\u1ed5ng SV", data: students },
            { name: "\u0110ang h\u1ecdc", data: studying },
            { name: "Ch\u1ec9 ti\u00eau", data: targets }
        ],
        chart: Object.assign({
            height: chartHeight,
            type: "line",
            zoom: { enabled: isFullscreen === true, type: "x", autoScaleYaxis: true }
        }, baseChartOpts),
        colors: [PRIMARY, SUCCESS, WARNING],
        stroke: {
            curve: "smooth",
            width: isFullscreen ? 4 : 3,
            dashArray: [0, 0, 8]
        },
        fill: {
            type: "gradient",
            gradient: {
                shade: "light",
                type: "vertical",
                shadeIntensity: 0.4,
                gradientToColors: ["#93c5fd", "#86efac", "#fdba74"],
                opacityFrom: isFullscreen ? 0.5 : 0.35,
                opacityTo: 0.04,
                stops: [0, 85, 100]
            }
        },
        markers: {
            size: isFullscreen ? 5 : 4,
