}

function renderScienceClassLineChart(byClassRows, filters) {
    var hasScience = isFilterValueActive(filters.scienceId);
    var pairs;
    var fullSeries;
    var previewPairs;
    var previewSeries;
    var noteEl;
    var titleEl;
    var options;
    var viewportHeight;

    if (!hasScience) {
        setScienceClassLineRowVisible(false);
        destroyChart("#scsDashChartScienceClassLine");
        scienceLineFullscreenState = null;
        return;
    }

    pairs = prepareClassLineData(byClassRows || []);
    setScienceClassLineRowVisible(true);

    if (pairs.length === 0) {
        destroyChart("#scsDashChartScienceClassLine");
        toggleChartEmpty("#scsDashChartScienceClassLine", "scsDashChartScienceClassLineEmpty", true);
        scienceLineFullscreenState = null;
        return;
    }

    toggleChartEmpty("#scsDashChartScienceClassLine", "scsDashChartScienceClassLineEmpty", false);

    titleEl = getEl("scsDashScienceClassLineTitle");
    if (titleEl) {
        titleEl.textContent = "S\u0129 s\u1ed1 l\u1edbp theo khoa \u0111\u00e3 ch\u1ecdn";
    }

    fullSeries = pairsToLineSeries(pairs);
    previewPairs = pairs.length > SCIENCE_LINE_PREVIEW_LIMIT ? pairs.slice(0, SCIENCE_LINE_PREVIEW_LIMIT) : pairs;
    previewSeries = pairsToLineSeries(previewPairs);

    noteEl = getEl("scsDashScienceClassLineNote");
    if (noteEl) {
        if (pairs.length > SCIENCE_LINE_PREVIEW_LIMIT) {
            noteEl.textContent = "Hi\u1ec3n th\u1ecb " + SCIENCE_LINE_PREVIEW_LIMIT + " l\u1edbp / " + formatNumber(pairs.length) + " \u2014 b\u1ea5m ph\u00f3ng to xem \u0111\u1ea7y \u0111\u1ee7.";
            noteEl.className = "scs-dash-chart-note";
        } else {
            noteEl.textContent = "";
            noteEl.className = "scs-dash-chart-note d-none";
        }
    }

    options = buildModernLineChartOptions(
        previewSeries.labels,
        previewSeries.students,
        previewSeries.studying,
        previewSeries.targets,
        340,
        false
    );
    renderChart("#scsDashChartScienceClassLine", options, null);

    scienceLineFullscreenState = {
        title: "S\u0129 s\u1ed1 l\u1edbp theo khoa",
        optionsBuilder: function () {
            viewportHeight = window.innerHeight || 800;
