    var btnOverview = getEl("scsDashBtnFullscreenOverview");
    var btnClass = getEl("scsDashBtnFullscreenClass");
    var btnScienceLine = getEl("scsDashBtnFullscreenScienceLine");
    var btnScienceBar = getEl("scsDashBtnFullscreenByScience");
    if (btnOverview) {
        btnOverview.disabled = !lastFullscreenState;
    }
    if (btnClass) {
        btnClass.disabled = !lastFullscreenState;
    }
    if (btnScienceLine) {
        btnScienceLine.disabled = !scienceLineFullscreenState;
    }
    if (btnScienceBar) {
        btnScienceBar.disabled = !scienceBarFullscreenState;
    }
}
function openFullscreen(customState) {
    var overlay = getEl("scsDashFullscreenOverlay");
    var titleEl = getEl("scsDashFullscreenTitle");
    var chartWrap = getEl("scsDashFullscreenChartWrap");
    var state = resolveFullscreenState(customState);
    var options;
    var layoutClass;
    if (!overlay || !state || !state.optionsBuilder) {
        return;
    }
    if (overlay.parentNode !== document.body) {
        document.body.appendChild(overlay);
    }
    if (titleEl) {
        titleEl.textContent = state.title || "Bi\u1ec3u \u0111\u1ed3 chi ti\u1ebft";
    }
    options = state.optionsBuilder();
    if (chartWrap && options && options.chart) {
        chartWrap.style.height = options.chart.height + "px";
    }
    renderChart("#scsDashChartPrimaryFullscreen", options, null);
    layoutClass = state.layoutMode === "line" ? "scs-dash-fullscreen-line" : "scs-dash-fullscreen-horizontal";
    overlay.className = "scs-dash-fullscreen " + layoutClass;
    document.body.style.overflow = "hidden";
    if (chartInstances["#scsDashChartPrimaryFullscreen"]) {
        chartInstances["#scsDashChartPrimaryFullscreen"].windowResizeHandler();
    }
}
